                  "features/voting.ts": "import type { Feature } from \"../src/server.ts\";\nexport const feature: Feature = {\n  id: \"voting\",\n  label: \"Vote on threads\",\n  setup(db) {\n    db.exec(\n      \"CREATE TABLE IF NOT EXISTS votes(postId INTEGER REFERENCES posts(id),userId TEXT REFERENCES users(id),PRIMARY KEY(postId,userId))\",\n    );\n  },\n  decorate(post, { db }) {\n    return {\n      ...post,\n      score: (\n        db\n          .prepare(\"SELECT COUNT(*) AS n FROM votes WHERE postId=?\")\n          .get(post.id) as any\n      ).n,\n    };\n  },\n  async handle(method, path, { db, user, send }) {\n    const match = /^\\/api\\/posts\\/(\\d+)\\/votes$/.exec(path);\n    if (method !== \"POST\" || !match) return false;\n    if (!db.prepare(\"SELECT id FROM posts WHERE id=?\").get(match[1])) {\n      send(404, { error: \"Post not found\" });\n      return true;\n    }\n    db.prepare(\"INSERT OR IGNORE INTO votes(postId,userId) VALUES(?,?)\").run(\n      match[1],\n      user,\n    );\n    send(200, {\n      score: (\n        db\n          .prepare(\"SELECT COUNT(*) AS n FROM votes WHERE postId=?\")\n          .get(match[1]) as any\n      ).n,\n    });\n    return true;\n  },\n};\n",
                  "test/voting.test.ts": "import test from \"node:test\";\nimport assert from \"node:assert/strict\";\nimport { session } from \"./helpers.ts\";\ntest(\"votes are idempotent per member and missing threads stay missing\", () =>\n  session(async (request) => {\n    const once = await request(\"/api/posts/1/votes\", { method: \"POST\" });\n    const twice = await request(\"/api/posts/1/votes\", { method: \"POST\" });\n    assert.equal(once.data.score, 1);\n    assert.equal(twice.data.score, 1);\n    assert.equal(\n      (await request(\"/api/posts/999/votes\", { method: \"POST\" })).status,\n      404,\n    );\n  }));\n",
                  "web/features/voting.js": "export async function mount({ posts, api, refresh, feed }) {\n  for (const post of posts) {\n    const actions = feed.querySelector(\n      `[data-post-id=\"${post.id}\"] [data-actions]`,\n    );\n    const vote = document.createElement(\"button\");\n    vote.textContent = \"↑ \" + post.score;\n    vote.onclick = async () => {\n      await api(\"/api/posts/\" + post.id + \"/votes\", { method: \"POST\" });\n      await refresh();\n    };\n    actions.prepend(vote);\n  }\n}\n"
